SELECT 'Behavioural Therapy — Student History Assessment','Confidential non-standardized case-history intake, based on Behavioural Therapy - Student History(1).pdf (7 pages). Preserves all 19 source sections and prompts. Record caregiver report separately from direct observation. Written responses only; no diagnostic score or severity threshold. The signature fields are written declarations, NOT verified digital signatures. Requires appropriate consent, confidentiality and qualified supervision.','all','[{"id":"s_BT_HISTORY_1","title":"Part 1 — Identification, concerns and development","categories":[{"id":"c_BT_HISTORY_01","title":"1. Identification details","questions":[{"id":"q_BT_HISTORY_01_01","text":"Client name","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_02","text":"Age / date of birth","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_03","text":"Gender","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_04","text":"Address","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_05","text":"Parent / guardian name","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_06","text":"Contact number","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_07","text":"Informant and relationship","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_08","text":"Referred by","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_01_09","text":"Intake date / therapist","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_02","title":"2. Chief complaints","questions":[{"id":"q_BT_HISTORY_02_01","text":"Main concerns","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_02_02","text":"Age first noticed / duration","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_02_03","text":"Current behavioural concerns","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_02_04","text":"Parent and child expectations","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_03","title":"3. History of presenting complaints","questions":[{"id":"q_BT_HISTORY_03_01","text":"Onset and progression","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_03_02","text":"Common triggers","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_03_03","text":"Behaviour at home","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_03_04","text":"Behaviour at school / social settings","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_03_05","text":"Factors that help","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_03_06","text":"Previous strategies and outcomes","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_04","title":"4. Birth history","questions":[{"id":"q_BT_HISTORY_04_01","text":"Prenatal: maternal health","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_02","text":"Medication / pregnancy complications","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_03","text":"Full-term / preterm","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_04","text":"Delivery type / birth weight","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_05","text":"Birth cry / birth complications","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_06","text":"NICU admission / neonatal jaundice","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_04_07","text":"Feeding or other postnatal difficulties","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_05","title":"5. Developmental history (age attained / remarks)","questions":[{"id":"q_BT_HISTORY_05_01","text":"Social smile / head control","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_05_02","text":"Sitting / crawling","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_05_03","text":"Standing / walking","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_05_04","text":"Babbling / first meaningful word","text_ml":"","response_type":"written"},{"id":"q