sentation / rapport","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_02","text":"Attention / activity level","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_03","text":"Task engagement","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_04","text":"Communication","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_05","text":"Social interaction","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_06","text":"Instruction following","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_07","text":"Emotional regulation / play","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_16_08","text":"Other behavioural observations","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_17","title":"17. Case history summary","questions":[{"id":"q_BT_HISTORY_17_01","text":"Child strengths","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_17_02","text":"Areas requiring support","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_17_03","text":"Parent / child priorities","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_17_04","text":"Preliminary impression","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_17_05","text":"Further assessment required","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_18","title":"18. Recommendations and initial plan","questions":[{"id":"q_BT_HISTORY_18_01","text":"Behavioural / skill assessment","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_18_02","text":"FBA if indicated","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_18_03","text":"Initial goals / parent training","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_18_04","text":"Home support / referrals","text_ml":"","response_type":"written"},{"id":"q_BT_HISTORY_18_05","text":"Session frequency / review date","text_ml":"","response_type":"written"}]},{"id":"c_BT_HISTORY_19","title":"19. Consent and authentication","question